// CORE START
const VMAX=600, ACC=440, BRAKE=540, REV_ACC=260, REV_MAX=120;
const STEER=3.4, STEER_LOSS=0.42, A_LAT=1250, K_LAT=16;
const W=60, RUNOFF=230, SP=10, KMH=0.55;
const HL=19, HW=7.5, INERTIA=(4*HL*HL+4*HW*HW)/12, CARW=2*HW; // coche a escala real: 5,6 m × 2 m (6,5 px/m)
const BOTDEC=0.74,BOTCRN=0.82,RL_MAX=46,L1F=0.97; // fracción de la frenada máxima que usan los bots
const PIT_LAT=W+65, PIT_BOX=W+99, PIT_V=150, PIT_HALF=26, BOT_BRAKE=BRAKE*0.66;
// modos de motor: ahorro / normal / ataque
const EMODES=[{n:'Ahorro',p:0.965,heat:0.55,fuel:0.88,wear:0.5},{n:'Normal',p:1,heat:1,fuel:1,wear:1},{n:'Ataque',p:1.035,heat:1.5,fuel:1.12,wear:2.2}];
const FUEL_RATE=0.17, WEAR_BASE=0.0058, TANK=100;
// --- física "simulación": escala real (6,5 px/m → 1 g = 63,8 px/s²) ---
const G=63.8, MECH=2.1, AERO=3.8, PWR=26500, ROLL=8, CD=(28000/600-ROLL)/(600*600), TRAC=1.25;
const LA=15, LB=15, LWB=LA+LB, IZ=170, CS=12, V_DYN=60;
function gripLat(c,v,R){ // aceleración lateral máxima (px/s²)
  const wf=0.75+0.5*(c.wing==null?0.5:c.wing),S=SURF[c.surf];
  const cf=c.cf||{aero:1,mech:1};
  const aero=AERO*cf.aero*wf*Math.min(1.2,(v/VMAX)*(v/VMAX))*(paved(c.surf)?1:0.3)/(1+0.14*c.fuel/TANK);
  return G*(MECH*cf.mech*S.grip*trackGrip(R,c)+aero)*tyreGrip(c)*(1-0.15*c.dWing)*(1-0.12*c.dSusp)*(c.punct?0.55:1)*(c.ooc>R.t?0.5:1);
}
// v45: temperatura (c.bT, °C) y desgaste (c.bW, 0-1) de los frenos de carbono.
// Fríos (<250 °C) muerden menos; muy calientes (>950 °C) pierden eficacia; gastados, algo menos de frenada.
function brakeTempF(c){const T=c.bT;if(T==null)return 1;
  const f=T<250?0.8+0.2*Math.max(0,T)/250:T>950?1-Math.min(0.38,(T-950)/420):1;
  return f*(1-0.14*Math.max(0,(c.bW||0)-0.4)/0.6);}
function brakeMax(c,v){return (1-(c.brakeFade||0))*brakeTempF(c)*G*(2.7+3.5*Math.min(1.2,(v/VMAX)*(v/VMAX))*(0.75+0.5*(c.wing==null?0.5:c.wing)))*(0.85+0.3*c.brakeS);}
function delMax(c,v,R){
  if(c.isPlayer&&!c.bot){ // jugador: tope = límite de agarre a velocidad; mucho más giro a poca velocidad; si el coche derrapa, se libera el volante para contravolantear
    const lo=clamp(1-v/260,0,1),sa=Math.sin(c.a),ca=Math.cos(c.a),vf=c.vx*ca+c.vy*sa,vl=-c.vx*sa+c.vy*ca,beta=Math.abs(Math.atan2(vl,Math.max(30,Math.abs(vf))));
    const k=(1.42-0.1*Math.min(1,v/VMAX)+1.2*lo)*(beta>0.1?1+Math.min(1.2,(beta-0.1)*6):1);
    // el volante no se “encoge” tanto con neumáticos fríos, gastados o en mojado: el coche desliza, pero gira
    const tg=Math.max(0.3,tyreGrip(c)),gl=gripLat(c,v,R)/tg*(0.55+0.45*tg);
    return Math.min(0.36+0.14*lo+(beta>0.1?0.12:0),Math.max(0.02,LWB*gl*k/Math.max(1,v*v)));}
  const k=2.0-0.8*Math.min(1,v/VMAX); // jugador: el tope del volante es el límite de agarre (girar sin gas no derrapa) // dirección progresiva: a alta velocidad el tope de giro queda cerca del límite de agarre
  return Math.min(0.32,Math.max(0.02,LWB*gripLat(c,v,R)*k/Math.max(1,v*v)));}
const COMPOUNDS={
  S:{name:'Blando',grip:1.07,wear:1.75,color:'#e53935',win:[78,105],heat:1.15},
  M:{name:'Medio',grip:1.0,wear:1.0,color:'#fdd835',win:[82,110],heat:1.0},
  H:{name:'Duro',grip:0.94,wear:0.6,color:'#f2f2f2',win:[88,118],heat:0.86},
  I:{name:'Intermedio',grip:1.0,wear:1.3,color:'#43a047',wet:true,win:[55,90],heat:1.0},
  W:{name:'Lluvia',grip:1.0,wear:1.2,color:'#1e88e5',wet:true,win:[45,80],heat:0.9}
};
// agarre según agua en la pista (0 seco … 1 encharcado)
function wetFactor(comp,w){
  if(comp==='I')return 0.82+0.06*Math.min(w/0.35,1)-0.2*Math.max(0,w-0.6)/0.4;
  if(comp==='W')return 0.74+0.10*Math.min(w/0.6,1);
  return 1-0.3*Math.min(w,1); // con secos en mojado: resbala bastante, pero el peligro real es el aquaplaning en los charcos
}
function wingAero(c,s){return 1+((c.wing==null?0.5:c.wing)-0.5)*0.45*Math.min(1,(s/VMAX)*(s/VMAX));}
const SURF={asphalt:{grip:1,drag:0.1},kerb:{grip:0.96,drag:0.12},concrete:{grip:0.86,drag:0.14},grass:{grip:0.42,drag:1.3},gravel:{grip:0.3,drag:2.6}};
const KERB=13; // ancho del piano (px): cuenta como pista
const GRAV_OUT=W+KERB+88; // la grava ocupa solo la franja junto a la pista; más allá, hierba
function paved(s){return s==='asphalt'||s==='kerb'||s==='concrete';}

function clamp(v,a,b){return v<a?a:v>b?b:v}
function angNorm(a){while(a>Math.PI)a-=2*Math.PI;while(a<-Math.PI)a+=2*Math.PI;return a}
function smooth(t){t=clamp(t,0,1);return t*t*(3-2*t)}
function rng(seed){return function(){seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}

