function crPoint(p0,p1,p2,p3,t){
  const d=(p,q)=>Math.max(1e-4,Math.sqrt(Math.hypot(q[0]-p[0],q[1]-p[1])));
  const t0=0,t1=d(p0,p1),t2=t1+d(p1,p2),t3=t2+d(p2,p3),tt=t1+(t2-t1)*t;
  const L=(A,B,ta,tb)=>{const u=(tt-ta)/(tb-ta);return [A[0]+(B[0]-A[0])*u,A[1]+(B[1]-A[1])*u];};
  const A1=L(p0,p1,t0,t1),A2=L(p1,p2,t1,t2),A3=L(p2,p3,t2,t3);
  const B1=L(A1,A2,t0,t2),B2=L(A2,A3,t1,t3);
  return L(B1,B2,t1,t2);
}

function minDist(tr,x,y,step){let m=1e18;for(let i=0;i<tr.N;i+=step){const dx=x-tr.xs[i],dy=y-tr.ys[i];const q=dx*dx+dy*dy;if(q<m)m=q;}return Math.sqrt(m);}
function dOf(tr,i){return i>tr.N/2?i-tr.N:i}
function lpPit(d){
  const a=W-30;
  if(d<=-100||d>=100)return a;
  if(d<-50)return a+(PIT_LAT-a)*smooth((d+100)/50);   // entrada y salida largas
  if(d>50)return PIT_LAT+(a-PIT_LAT)*smooth((d-50)/50);
  return PIT_LAT;
}
let BOX_STEP=5.4;function boxD(slot){return -40+slot*BOX_STEP} // con parrilla llena los boxes se juntan para caber en el pit lane
// muro que separa el pit lane de la pista (null donde el carril aún va pegado a la pista)
function pitWallLat(d){if(d<-100||d>100)return null;if(d>=-50&&d<=50)return W+30;const inner=lpPit(d)-PIT_HALF;return inner>W+KERB+10?(W+KERB+2+inner)/2:null;}

const TRACK_CACHE={};
/* v45: la foto aérea de Montmeló es opcional (Ajustes); por defecto el circuito se dibuja como los demás, nítido a cualquier zoom */
let USE_PHOTO=false;function setUsePhoto(v){v=!!v;if(USE_PHOTO!==v){USE_PHOTO=v;for(const k in TRACK_CACHE)delete TRACK_CACHE[k];}}
function buildTrack(ti){
  if(TRACK_CACHE[ti])return TRACK_CACHE[ti];
  const def=TRACKS[ti];
  let P=def.pts.map(p=>[p[0]*def.scale,p[1]*def.scale]);
  if(def.rev)P=[P[0]].concat(P.slice(1).reverse()); // sentido real de carrera
  const n=P.length,dense=[];
  for(let i=0;i<n;i++){const p0=P[(i-1+n)%n],p1=P[i],p2=P[(i+1)%n],p3=P[(i+2)%n];const sub=def.sub||80;for(let s=0;s<sub;s++)dense.push(crPoint(p0,p1,p2,p3,s/sub));}
  const D=dense.length,cum=new Float64Array(D+1);
  for(let i=1;i<=D;i++){const a=dense[i-1],b=dense[i%D];cum[i]=cum[i-1]+Math.hypot(b[0]-a[0],b[1]-a[1]);}
  const len=cum[D],N=Math.round(len/SP),sp=len/N;
  const F=()=>new Float64Array(N);
  const xs=F(),ys=F(),tx=F(),ty=F(),nx=F(),ny=F(),ang=F(),k=F(),vLim=F(),vA=F();
  let j=0;
  for(let i=0;i<N;i++){const d=i*sp;while(j<D-1&&cum[j+1]<d)j++;const a=dense[j],b=dense[(j+1)%D],t=(d-cum[j])/((cum[j+1]-cum[j])||1);xs[i]=a[0]+(b[0]-a[0])*t;ys[i]=a[1]+(b[1]-a[1])*t;}
  for(let i=0;i<N;i++){const p=(i-1+N)%N,q=(i+1)%N;let dx=xs[q]-xs[p],dy=ys[q]-ys[p];const l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;tx[i]=dx;ty[i]=dy;nx[i]=-dy;ny[i]=dx;ang[i]=Math.atan2(dy,dx);}
  for(let i=0;i<N;i++)k[i]=angNorm(ang[(i+4)%N]-ang[(i-4+N)%N])/(8*sp);
  for(let i=0;i<N;i++){const ak=Math.abs(k[i])+1e-6;vA[i]=Math.min(VMAX,STEER/(1.3*ak+STEER*STEER_LOSS/VMAX),Math.sqrt(0.86*A_LAT/ak));}
  for(let i=0;i<N;i++){let m=1e9;for(let d=-4;d<=4;d++)m=Math.min(m,vA[(i+d+N)%N]);vLim[i]=m;}
  for(let r=0;r<3;r++)for(let i=N-1;i>=0;i--){const v=vLim[(i+1)%N];vLim[i]=Math.min(vLim[i],Math.sqrt(v*v+2*BOT_BRAKE*sp));}
  /* v46: trazada ideal. Los bots iban por el centro de la pista y un humano, abriéndose y buscando el vértice, pasaba mucho más rápido.
     Camino de curvatura mínima dentro de la pista (suavizado de 4.º orden a varias escalas), con margen para los bordillos. */
  const rl=new Float64Array(N),RX=new Float64Array(N),RY=new Float64Array(N),LM=RL_MAX;
  {const Px=i=>xs[i]+nx[i]*rl[i],Py=i=>ys[i]+ny[i]*rl[i];
   for(const st of [12,6,3,2,1])for(let it=0;it<(st===1?300:120);it++)for(let i=0;i<N;i++){const a=(i-st+N)%N,b=(i+st)%N,a2=(i-2*st+N)%N,b2=(i+2*st)%N;
     const mx=(4*(Px(a)+Px(b))-Px(a2)-Px(b2))/6,my=(4*(Py(a)+Py(b))-Py(a2)-Py(b2))/6;
     rl[i]=clamp((mx-xs[i])*nx[i]+(my-ys[i])*ny[i],-LM,LM);}
   for(let i=0;i<N;i++){RX[i]=Px(i);RY[i]=Py(i);}}
  const angR=new Float64Array(N),segR=new Float64Array(N);
  for(let i=0;i<N;i++){const p=(i-1+N)%N,q=(i+1)%N;angR[i]=Math.atan2(RY[q]-RY[p],RX[q]-RX[p]);segR[i]=Math.hypot(RX[q]-RX[i],RY[q]-RY[i]);}
  const vLimS=new Float64Array(N);{const cc=0.9*G*AERO/(VMAX*VMAX);const vS=new Float64Array(N);
    const kw=new Float64Array(N),kR=new Float64Array(N);for(let i=0;i<N;i++){const a=(i-9+N)%N,b=(i+9)%N,a4=(i-4+N)%N,b4=(i+4)%N;
      kw[i]=Math.abs(angNorm(angR[b]-angR[a]))/Math.max(1,Math.hypot(RX[b]-RX[a],RY[b]-RY[a])); // curvatura media de la trazada (filtra ruido GPS)
      kR[i]=Math.abs(angNorm(angR[b4]-angR[a4]))/Math.max(1,Math.hypot(RX[b4]-RX[a4],RY[b4]-RY[a4]));}
    for(let i=0;i<N;i++){const ak=Math.max(kw[i],kR[i]*0.6);vS[i]=ak<=cc?VMAX*1.05:Math.min(VMAX*1.05,Math.sqrt(BOTCRN*G*MECH/(ak-cc)));}
    for(let i=0;i<N;i++){let m=1e9;for(let d=-4;d<=4;d++)m=Math.min(m,vS[(i+d+N)%N]);vLimS[i]=m;}
    var vCornS=Float32Array.from(vLimS); // velocidad de paso por curva, sin la frenada (para la frenada tardía de los bots)
    var vWetS=Float64Array.from(vLimS);for(let r=0;r<3;r++)for(let i=N-1;i>=0;i--){const v=vWetS[(i+1)%N],dec=0.5*G*(2.7+3.5*Math.min(1,v*v/(VMAX*VMAX)));vWetS[i]=Math.min(vWetS[i],Math.sqrt(v*v+2*dec*segR[i]));} // frenada prudente en mojado
    for(let r=0;r<3;r++)for(let i=N-1;i>=0;i--){const v=vLimS[(i+1)%N],dec=BOTDEC*G*(2.7+3.5*Math.min(1,v*v/(VMAX*VMAX))); /* frenada fuerte y tardía */vLimS[i]=Math.min(vLimS[i],Math.sqrt(v*v+2*dec*segR[i]));}}
  const corner=new Uint8Array(N);
  for(let i=0;i<N;i++){for(let d=-8;d<=8;d++)if(Math.abs(k[(i+d+N)%N])>1/1000){corner[i]=1;break;}}
  // escapatorias exteriores de las curvas: grava o asfalto/hormigón (como en los circuitos modernos); por dentro, hierba
  const outSide=new Int8Array(N),outSurf=new Uint8Array(N);
  {const R2=rng(ti*31+7);let q0=0;while(q0<N&&corner[q0])q0++;
   for(let q=0;q<N;q++){const i=(q0+q)%N;if(corner[i]&&!corner[(i-1+N)%N]){
     let e=i,sgn=0,km=0;while(corner[e%N]&&e-i<N){const kk=k[e%N];if(Math.abs(kk)>km){km=Math.abs(kk);sgn=-Math.sign(kk);}e++;}
     const type=R2()<0.65?2:1;for(let j=i-6;j<e+(type===2?22:10);j++){const jj=((j%N)+N)%N;outSide[jj]=sgn;outSurf[jj]=type;}}}}
  const tr={rl,vCorn:(typeof vCornS!=="undefined"?vCornS:null),vWet:(typeof vWetS!=="undefined"?vWetS:null),name:def.name,country:def.country,ti,N,sp,len,xs,ys,tx,ty,nx,ny,ang,k,vLim,vLimS,corner,outSide,outSurf};
  // charcos: mismos que dibuja el juego (misma semilla); se llenan cuando hay mucha agua en ese punto
  {const Rp=rng(ti*97+3),pud=[];for(let q=0;q<Math.round(N/12);q++){const i=Math.floor(Rp()*N),lat=(Rp()-0.5)*2*(W-18);const rx=14+Rp()*26,ry=8+Rp()*12;Rp();pud.push({i,lat,rx,ry,th:0.45+Rp()*0.4});}
   tr.pud=pud;tr.pudIdx=new Map();for(const p of pud){const n=Math.ceil(p.rx/sp)+1;for(let d=-n;d<=n;d++){const j=((p.i+d)%N+N)%N;if(!tr.pudIdx.has(j))tr.pudIdx.set(j,[]);tr.pudIdx.get(j).push(p);}}}
  {let best=0,bs=0,run=0,st=0;for(let q=0;q<2*N;q++){const i=q%N;if(!corner[i]){if(run===0)st=q;run++;if(run>best&&run<N){best=run;bs=st;}}else run=0;}
   tr.drsFrom=(bs+Math.round(best*0.12))%N;tr.drsLen=Math.round(best*0.8);tr.drsDetect=(tr.drsFrom-35+N)%N;}
  // lado de boxes: el que tenga más espacio libre
  let best=-1,side=1;
  for(const s of [1,-1]){let m=1e9;for(const d of [-60,0,60]){const i=(d+N)%N;m=Math.min(m,minDist(tr,xs[i]+nx[i]*s*(RUNOFF+260),ys[i]+ny[i]*s*(RUNOFF+260),2));}if(m>best){best=m;side=s;}}
  tr.pitSide=def.pitSide||side;
  if(def.photo&&USE_PHOTO){const ph=def.photo,mx=111320*Math.cos(ph.latm*Math.PI/180),PPM=6.5;
    const rect=t=>({src:t.src,x0:(t.lon[0]-ph.lon0)*mx*PPM,x1:(t.lon[1]-ph.lon0)*mx*PPM,y0:-(t.lat[1]-ph.lat0)*111320*PPM,y1:-(t.lat[0]-ph.lat0)*111320*PPM});
    tr.photo={credit:ph.credit,low:[rect(ph.low)],hi:(ph.hi||[]).map(rect)};}
  // tribunas en el lado opuesto, si caben
  let standsOk=true;
  for(let d=-56;d<=56;d+=8){const i=(d+N)%N;const s=-side;if(minDist(tr,xs[i]+nx[i]*s*(RUNOFF+110),ys[i]+ny[i]*s*(RUNOFF+110),2)<RUNOFF+100){standsOk=false;break;}}
  tr.stands=standsOk;
  // árboles
  const R=rng(ti*7919+13),trees=[];
  let minX=1e9,maxX=-1e9,minY=1e9,maxY=-1e9;for(let i=0;i<N;i++){minX=Math.min(minX,xs[i]);maxX=Math.max(maxX,xs[i]);minY=Math.min(minY,ys[i]);maxY=Math.max(maxY,ys[i]);}
  tr.bounds={minX,maxX,minY,maxY};
  for(let a=0;a<2200;a++){
    const x=minX-700+R()*(maxX-minX+1400),y=minY-700+R()*(maxY-minY+1400);
    const md=minDist(tr,x,y,2);
    if(md<RUNOFF+45)continue;
    if(Math.hypot(x-xs[0],y-ys[0])<1100&&md<380)continue;
    trees.push({x,y,r:16+R()*20,s:R()});
  }
  // entorno tipo foto aérea: campos de cultivo, naves y casas, aparcamiento del paddock y carretera de acceso
  {const E=rng(ti*4421+7),W0=maxX-minX,H0=maxY-minY,env={fields:[],bld:[],park:[],roads:[]};
   const free=(x,y,m)=>minDist(tr,x,y,3)>m;
   for(let k=0;k<26;k++){const w=900+E()*1800,h=600+E()*1400;env.fields.push({x:minX-1500+E()*(W0+3000),y:minY-1500+E()*(H0+3000),w,h,a:(E()-0.5)*0.8,t:Math.floor(E()*5),st:E()<0.6});}
   // aparcamiento detrás de los garajes
   {const i0=0,s2=side,off=RUNOFF+150;const cx=xs[i0]+nx[i0]*s2*(off+170),cy=ys[i0]+ny[i0]*s2*(off+170);
    if(free(cx,cy,RUNOFF+160))env.park.push({x:cx,y:cy,w:900,h:300,a:ang[i0],seed:ti});
    // carretera de acceso desde el aparcamiento hacia fuera
    const pts=[];for(let r=0;r<3200;r+=80){const x=cx+nx[i0]*s2*(170+r),y=cy+ny[i0]*s2*(170+r);if(!free(x,y,RUNOFF+60))break;pts.push([x,y]);}
    if(pts.length>4)env.roads.push(pts);}
   // grupos de edificios lejos de la pista
   for(let k=0,tries=0;k<7&&tries<200;tries++){const x=minX-1200+E()*(W0+2400),y=minY-1200+E()*(H0+2400);if(!free(x,y,RUNOFF+420))continue;k++;
     const a=(E()-0.5)*1.2,n=3+Math.floor(E()*6),ind=E()<0.4;
     for(let j=0;j<n;j++){const u=(E()-0.5)*520,v=(E()-0.5)*360,bx=x+Math.cos(a)*u-Math.sin(a)*v,by=y+Math.sin(a)*u+Math.cos(a)*v;
       const w=ind?160+E()*200:50+E()*70,h=ind?90+E()*110:40+E()*50;if(!free(bx,by,RUNOFF+200+Math.max(w,h)/2))continue;
       env.bld.push({x:bx,y:by,w,h,a,ind,c:Math.floor(E()*4)});}
     // camino que une el grupo con la carretera más cercana (o hacia fuera)
   }
   tr.env=env;
   const inRect=(t,r,pad)=>{const dx=t.x-r.x,dy=t.y-r.y,c=Math.cos(r.a),s3=Math.sin(r.a),u=dx*c+dy*s3,v=-dx*s3+dy*c;return Math.abs(u)<r.w/2+pad&&Math.abs(v)<r.h/2+pad;};
   tr.trees=trees.filter(t=>!env.bld.some(b=>inRect(t,b,30))&&!env.park.some(p=>inRect(t,p,40))&&!env.roads.some(rd=>rd.some(q=>Math.hypot(t.x-q[0],t.y-q[1])<60)));}
  if(!tr.trees)tr.trees=trees;
  if(def.photo&&USE_PHOTO){tr.trees=[];tr.env=null;} // con foto aérea real: árboles y edificios ya salen en la foto
  // muro intermedio donde otro tramo pasa cerca: límite lateral por lado
  const limP=new Float32Array(N),limM=new Float32Array(N);limP.fill(RUNOFF-14);limM.fill(RUNOFF-14);
  for(let i=0;i<N;i++)for(let j=0;j<N;j+=2){
    let dd=Math.abs(i-j);dd=Math.min(dd,N-dd);if(dd*sp<700)continue;
    const vx=xs[j]-xs[i],vy=ys[j]-ys[i];if(Math.abs(vx)>2*RUNOFF+60||Math.abs(vy)>2*RUNOFF+60)continue;
    const lat=vx*nx[i]+vy*ny[i],al=vx*tx[i]+vy*ty[i];
    if(Math.abs(al)<Math.abs(lat)*0.7){const lim=Math.abs(lat)/2-6;if(lat>0){if(lim<limP[i])limP[i]=lim;}else{if(lim<limM[i])limM[i]=lim;}}
  }
  tr.limP=limP;tr.limM=limM;
  TRACK_CACHE[ti]=tr;
  // charcos (mismos que se dibujan): la física los conoce para el aquaplaning
  {const Rp=rng(ti*97+3),P=[];for(let k=0;k<Math.round(N/12);k++){const i=Math.floor(Rp()*N),lat=(Rp()-0.5)*2*(W-18);P.push({i,lat,x:xs[i]+nx[i]*lat,y:ys[i]+ny[i]*lat,rx:14+Rp()*26,ry:8+Rp()*12,a:ang[i]+(Rp()-0.5)*0.6,th:0.45+Rp()*0.4});}
   tr.puddles=P;tr.pudAt=new Map();P.forEach((p,k)=>{const n=Math.ceil(p.rx/sp)+1;for(let d=-n;d<=n;d++){const j=((p.i+d)%N+N)%N;if(!tr.pudAt.has(j))tr.pudAt.set(j,[]);tr.pudAt.get(j).push(k);}});}
  return tr;
}

// ---------- tiempo: nubes que cruzan con el viento + microclima fijo por circuito ----------
function makeWeather(tr,type,seed){
  const Rr=rng(seed||1),b=tr.bounds,cx=(b.minX+b.maxX)/2,cy=(b.minY+b.maxY)/2,diag=Math.hypot(b.maxX-b.minX,b.maxY-b.minY);
  const Wt={type,t:0,cells:[],acc:0};
  const Rz=rng(tr.ti*31+7),zones=[];
  for(let i=0;i<4;i++)zones.push({x:b.minX+Rz()*(b.maxX-b.minX),y:b.minY+Rz()*(b.maxY-b.minY),r:1500+Rz()*2500,f:(Rz()-0.4)*1.1});
  Wt.zones=zones;
  const wa=Rr()*Math.PI*2,ws=40+Rr()*35;Wt.wx=Math.cos(wa)*ws;Wt.wy=Math.sin(wa)*ws;
  // tiempo variable: chubascos locales, frente amplio que cubre todo el circuito, o mezcla
  const sc=type==='var'?Rr():0;Wt.scen=type!=='var'?type:sc<0.4?'chubascos':sc<0.75?'frente':'mixto';
  const n=type==='rain'?3:type==='var'?3:0;
  for(let k=0;k<n;k++){
    const back=type==='rain'?(Rr()-0.5)*diag:diag*(0.55+k*0.45+Rr()*0.35),side=(Rr()-0.5)*diag*0.7;
    const px=-Math.sin(wa),py=Math.cos(wa);
    const big=Wt.scen==='frente'?k===0:Wt.scen==='mixto'?k===1:false;
    Wt.cells.push(big?{x0:cx-Math.cos(wa)*back,y0:cy-Math.sin(wa)*back,r:diag*(0.75+Rr()*0.3),int:0.75+Rr()*0.35}
      :{x0:cx-Math.cos(wa)*back+px*side,y0:cy-Math.sin(wa)*back+py*side,r:1800+Rr()*2200,int:type==='rain'?0.3+Rr()*0.35:0.55+Rr()*0.5});
  }
  /* v46: sorpresas contra la previsión. Chaparrón que se forma encima del circuito (el radar no lo ve hasta que nace)
     o nubes que se deshacen / lluvia que para antes de tiempo (el radar daba que seguiría). */
  Wt.sur=[];
  if(type==='var'&&Rr()<0.45){const t0=50+Rr()*380,pxs=b.minX+(0.25+0.5*Rr())*(b.maxX-b.minX),pys=b.minY+(0.25+0.5*Rr())*(b.maxY-b.minY),dur=150+Rr()*200;
    Wt.cells.push({x0:pxs-Wt.wx*(t0+dur*0.35),y0:pys-Wt.wy*(t0+dur*0.35),r:1700+Rr()*1600,int:0.75+Rr()*0.45,born:t0,die:t0+dur,hid:true});Wt.sur.push({t:t0,kind:'shower'});}
  if(type==='var'&&Rr()<0.3){const c=Wt.cells[Math.floor(Rr()*Math.min(3,Wt.cells.length))];if(c&&!c.hid){c.die=60+Rr()*300;c.hid=true;Wt.sur.push({t:c.die,kind:'clear'});}}
  if(type==='rain'&&Rr()<0.3){Wt.clearT=120+Rr()*360;for(const c of Wt.cells){c.die=Wt.clearT+Rr()*40;c.hid=true;}Wt.sur.push({t:Wt.clearT,kind:'clear'});}
  Wt.zoneS=new Float32Array(tr.N);Wt.rainS=new Float32Array(tr.N);
  for(let i=0;i<tr.N;i++)Wt.zoneS[i]=zoneAt(Wt,tr.xs[i],tr.ys[i]);
  return Wt;
}
function zoneAt(Wt,x,y){let z=1;for(const q of Wt.zones){const d2=((x-q.x)**2+(y-q.y)**2)/(q.r*q.r);if(d2<4)z+=q.f*Math.exp(-d2);}return clamp(z,0.45,1.6);}
function cellPos(Wt,c){return [c.x0+Wt.wx*Wt.t,c.y0+Wt.wy*Wt.t];}
/* cuánto existe una nube en el instante t (nace en ~70 s y se deshace en ~90 s). El radar (previsión) solo sabe lo que hay ahora */
function cellLife(Wt,c,t){if(c.born==null&&c.die==null)return 1;const tk=Wt.fc!=null&&c.hid?Wt.fc:t;let f=1;
  if(c.born!=null)f=Math.min(f,clamp((tk-c.born)/70,0,1));if(c.die!=null)f=Math.min(f,clamp(1-(tk-c.die)/90,0,1));return f;}
function rainAt(Wt,x,y,zone){
  if(!Wt||Wt.type==='dry')return 0;
  let r=Wt.type==='rain'?(0.42+0.18*Math.sin(Wt.t/38))*(Wt.clearT!=null?clamp(1-((Wt.fc!=null?Wt.fc:Wt.t)-Wt.clearT)/120,0,1):1):0;
  for(const c of Wt.cells){const lf=cellLife(Wt,c,Wt.t);if(lf<=0)continue;const [px,py]=cellPos(Wt,c),d=Math.hypot(x-px,y-py)/c.r;if(d<1)r+=c.int*lf*smooth(1-d);}
  return clamp(r*(zone==null?zoneAt(Wt,x,y):zone),0,1.1);
}
// agua media prevista en la pista en los instantes indicados (s desde ahora): lo que “ve” el radar del equipo
// agua relevante para elegir goma: la que hay ahora y la que dice el radar para la próxima vuelta
function wetNeed(R,c){if(!R.weather||R.weather.type==='dry')return 0;const lap=(c&&c.lastLap)||(R.est&&R.est.lap)||90;
  const now=Math.max(R.meanWet||0,0.8*((c&&c.wetFelt)||0)),f=(forecastWet(R,[lap*0.3])+forecastWet(R,[lap*0.7])+forecastWet(R,[lap*1.1]))/3;
  return 0.35*now+0.65*f;} // lo que importa es el agua que habrá durante el próximo stint, no la de este instante
function compoundFor(R,c,k){const w=wetNeed(R,c);if(w>0.58)return 'W';if(w>0.17)return COMPOUNDS[k].wet?k:'I';
  if(COMPOUNDS[k].wet&&w<0.07)return chooseCompound(Math.max(1,lapsLeft(R,c)-1),R.est,Math.random());return k;}
function forecastWet(R,times){const Wt=R.weather,tr=R.tr,t0=Wt.t;let m=0;Wt.fc=t0;
  for(const dt of times){Wt.t=t0+dt;let s=0,n=0;for(let i=0;i<tr.N;i+=6){s+=Math.min(1,rainAt(Wt,tr.xs[i],tr.ys[i],Wt.zoneS[i])*1.35);n++;}m=Math.max(m,s/n);}
  Wt.t=t0;Wt.fc=null;return m;}
function stepWeather(R,dt){
  const Wt=R.weather;if(!Wt||Wt.type==='dry')return;
  Wt.t+=dt;Wt.acc+=dt;
  if(Wt.sur)for(const q of Wt.sur)if(!q.done&&Wt.t>=q.t+(q.kind==='shower'?25:30)){q.done=true;if(R.fx)R.events.push({type:'wxsurprise',kind:q.kind});}
  if(Wt.acc<0.2)return;const h=Wt.acc;Wt.acc=0;
  const tr=R.tr,water=R.water;let sum=0;
  for(let i=0;i<tr.N;i++){
    const r=rainAt(Wt,tr.xs[i],tr.ys[i],Wt.zoneS[i]);Wt.rainS[i]=r;
    const target=Math.min(1,r*1.35),w0=water[i];
    water[i]=clamp(w0+(target-w0)*(target>w0?0.07:0.016)*h,0,1);sum+=water[i];
    if(r>0.15&&R.dry)R.dry[i]*=Math.exp(-0.35*r*h); // si vuelve a llover, la trazada se moja otra vez
  }
  R.meanWet=sum/tr.N;
  // las nubes que ya han cruzado vuelven a entrar por el otro lado (en modo variable, a veces)
  const b=tr.bounds,diag=Math.hypot(b.maxX-b.minX,b.maxY-b.minY),cx=(b.minX+b.maxX)/2,cy=(b.minY+b.maxY)/2;
  for(const c of Wt.cells){const [px,py]=cellPos(Wt,c);const along=((px-cx)*Wt.wx+(py-cy)*Wt.wy)/Math.hypot(Wt.wx,Wt.wy);
    if(along>diag*0.7+c.r){const ws=Math.hypot(Wt.wx,Wt.wy),back=diag*(0.7+Math.random()*(Wt.type==='var'?1.6:0.3));
      c.x0=cx-Wt.wx/ws*back-Wt.wx*Wt.t+(Math.random()-0.5)*(-Wt.wy/ws)*diag*0.7;c.y0=cy-Wt.wy/ws*back-Wt.wy*Wt.t+(Math.random()-0.5)*(Wt.wx/ws)*diag*0.7;
      c.int=Wt.type==='rain'?0.3+Math.random()*0.35:0.45+Math.random()*0.6;}}
}
function locate(tr,c){
  let best=1e18,bi=c.idx;
  for(let d=-40;d<=40;d++){const i=(c.idx+d+tr.N)%tr.N;const dx=c.x-tr.xs[i],dy=c.y-tr.ys[i];const q=dx*dx+dy*dy;if(q<best){best=q;bi=i;}}
  c.idx=bi;c.lat=(c.x-tr.xs[bi])*tr.nx[bi]+(c.y-tr.ys[bi])*tr.ny[bi];
}
function onPitLane(tr,c){const d=dOf(tr,c.idx);if(d<-102||d>102)return false;const sl=c.lat*tr.pitSide;if(d>=-52&&d<=52)return sl>W-5&&sl<PIT_BOX+24;return Math.abs(sl-lpPit(d))<PIT_HALF+4;}

const DIFF={facil:[0.84,0.93],normal:[0.91,0.985],dificil:[0.96,1.035],experto:[1.0,1.06]};

// carácter de cada piloto: si no se ha definido a mano, se deriva de su nombre (siempre el mismo para el mismo piloto)
const STYLES={defensor:{n:'defiende muy duro',def:0.92},agresivo:{n:'muy agresivo atacando',agr:0.92},cuidadoso:{n:'cuida mucho los neumáticos',bru:0.05},rompe:{n:'castiga mucho los neumáticos',bru:0.8},metronomo:{n:'un metrónomo, casi no falla',reg:0.95},irregular:{n:'rápido pero irregular, comete errores',reg:0.15,agr:0.7}};
function driverTraits(d){
  if(d.player)return {agr:0.5,def:0.5,reg:0.5,bru:0.3};
  let h=0;for(const ch of (d.name||'x'))h=(h*31+ch.charCodeAt(0))>>>0;const Rn=rng(h);
  const keys=Object.keys(STYLES),st=d.style||keys[h%keys.length],S=STYLES[st];
  const t={agr:0.35+Rn()*0.3,def:0.35+Rn()*0.3,reg:0.4+Rn()*0.3,bru:0.2+Rn()*0.2,style:st};
  for(const k of ['agr','def','reg','bru'])if(S[k]!=null)t[k]=S[k];
  for(const k of ['agr','def','reg','bru'])if(d[k]!=null)t[k]=d[k]/100;
  return t;}
