  const L1=R.mode==='race'&&R.phase==='race'&&c.lap<=1&&!c.isPlayer;
  // v44: menos prudencia (antes frenaban un 6 % antes y dejaban casi el doble de hueco: las salidas eran un paseo)
  if(L1&&vl0<VMAX*0.95)target*=L1F;
