  const massF=1+0.28*c.fuel/TANK;
  const aeroBoost=1+0.035*c.slip+(c.drsOpen?0.05:0)+(c.kersOn?0.025:0);
  const vmax=VMAX*aeroBoost*(0.96+0.08*c.gearS)*(c.isPlayer?1:c.skill)*(1.035-0.07*(c.wing==null?0.5:c.wing))*(1-0.05*c.dWing)*(1-0.1*c.dRear)*(c.punct?0.75:1);
