  let braking=false;
  if(c.brake>0){if(vf>2){aL-=BRAKE*(0.85+0.3*c.brakeS)*(0.72+0.38*Math.min(1,vf/VMAX))*c.brake;braking=true;c.kers=Math.min(4,c.kers+c.brake*0.45*dt);}else if(c.brake>0.6)aL-=REV_ACC*c.brake;}
