    if((c.bot||R.aids)&&!(c.noESC>R.t)){const rRef=pl?rGrip:rKin;
      if(Math.abs(ar)>0.10){dr-=(c.r-rRef)*5;ax-=Math.max(0,FxR)*0.6;}}
